# Fill the triangle between forward diagonal (c = r + 1) and right backward diagonal (c = 13 - r)
# For r in [4, 6]

grid_shape = (14, 24)

output_triangle = [[3]*24 for _ in range(14)]

for r in range(14):
    for c in range(24):
        # Triangle region
        if 4 <= r <= 6:
            if c >= r + 1 and c <= 13 - r:
                output_triangle[r][c] = 0

print("Testing triangle fill:")
for r in range(14):
    row_str = ' '.join(['0' if output_triangle[r][c] == 0 else '3' 
                        for c in range(24)])
    print(f"r={r}: {row_str}")

